const body = $input.first().json.body || $input.first().json;
// n8n puts the POST body under .body; fall back to the item itself when testing.

const grid = body.grid || {};
const schema = Array.isArray(body.schema) ? body.schema : [];
const products = Array.isArray(body.products) ? body.products : [];
if (!Array.isArray(grid.cells) || grid.cells.length === 0) throw new Error('grid.cells must contain at least one cell');
if (schema.length === 0) throw new Error('schema must contain at least one tag');
if (products.length === 0) throw new Error('products must contain at least one product');
// The logged-in user's details and the reference number are NOT sent to the model: the backend fills account-manager tags itself
// (see "userSource") and the reference number is built by the "Build Reference" node from the quotation reference the AI reads.

const prompt = [
  'TODAY: ' + (body.today || ''),
  'ROW FLAG KEY: "' + (body.groupFlag || '_group') + '" - on every heading row and every total / sub-total row of a loop that is built from the Excel, add this key to that row object as the JSON boolean true (e.g. {"item": "Total", ..., "' + (body.groupFlag || '_group') + '": true}). Do not add it to other rows.',
  '',
  'SELECTED SLT PRODUCTS (' + products.length + ', in this order; terms are the exact text to copy for product terms):',
  JSON.stringify(products.map(function (p) { return { id: p.id, name: p.name, pillar: p.pillar, description: p.description, features: p.features, customerBenefits: p.customerBenefits, termsAndConditions: p.termsAndConditions }; })),
  '',
  'TAG SCHEMA (the tags of the Word template you must fill, read from the active template just now; "context" is the template text around the tag, "section" the heading it sits under, children = the fields of a loop):',
  JSON.stringify(schema),
  '',
  'SHEET "' + (grid.sheetName || '') + '" - MERGED RANGES (the content of a merged range is in its top-left cell):',
  JSON.stringify((grid.merges || []).map(function (m) { return m.range; })),
  '',
  'SHEET CELLS - every non-empty cell as {a: address, v: value[, t: displayed text]}; t = what the sheet displays when it differs from v:',
  JSON.stringify(grid.cells.map(function (c) { var o = { a: c.address, v: c.value }; if (c.text) o.t = c.text; return o; }))
].join('\n');

return [{ json: { prompt: prompt, schema: schema, products: products } }];

const schema = $('Build Prompt').first().json.schema || [];
// Only tag names from the schema are ever returned; the backend checks the answer again.

let raw = String($input.first().json.output || '').trim();

// Repairs the usual faults of a model's JSON: trailing commas, raw line breaks / tabs inside strings, unescaped double quotes inside
// string values (65" screen), and an answer cut off in the middle (open string / brackets are closed).
function repairJson(text) {
  let out = '';
  const stack = [];
  let inStr = false;
  const n = text.length;
  for (let i = 0; i < n; i++) {
    const c = text[i];
    if (inStr) {
      if (c === '\\') {
        const nx = text[i + 1];
        if (nx !== undefined && '"\\/bfnrtu'.indexOf(nx) !== -1) { out += c + nx; i++; } else { out += '\\\\'; }
        continue;
      }
      if (c === '"') {
        let j = i + 1;
        while (j < n && /\s/.test(text[j])) j++;
        const nx = text[j];
        const top = stack[stack.length - 1];
        // a real closing quote is followed by : , } ] or the end of the text
        let closes = nx === undefined || nx === ':' || nx === '}' || nx === ']';
        if (nx === ',') {
          let k = j + 1;
          while (k < n && /\s/.test(text[k])) k++;
          const after = text[k];
          closes = after === undefined || '"{[]}-0123456789tfn'.indexOf(after) !== -1;
        }
        if (nx === ':' && top !== '{') closes = false;
        if (closes) { inStr = false; out += c; } else { out += '\\"'; }
        continue;
      }
      if (c === '\n') { out += '\\n'; continue; }
      if (c === '\r') { continue; }
      if (c === '\t') { out += '\\t'; continue; }
      out += c;
      continue;
    }
    if (c === '"') { inStr = true; out += c; continue; }
    if (c === '{' || c === '[') { stack.push(c); out += c; continue; }
    if (c === '}' || c === ']') {
      out = out.replace(/,\s*$/, '');
      stack.pop();
      out += c;
      continue;
    }
    out += c;
  }
  if (inStr) out += '"';
  out = out.replace(/,\s*$/, '').replace(/:\s*$/, ': ""');
  while (stack.length) { out = out.replace(/,\s*$/, ''); out += stack.pop() === '{' ? '}' : ']'; }
  return out;
}

function tryParse(text) {
  try { const v = JSON.parse(text); return v && typeof v === 'object' && !Array.isArray(v) ? v : null; } catch (e) { return null; }
}

// 1) the text as it is, 2) without ``` / ```json fences, 3) the outermost { ... } of the text, 4) each of those repaired
const unfenced = raw.replace(/```[a-zA-Z]*/g, '').trim();
const start = unfenced.indexOf('{');
const end = unfenced.lastIndexOf('}');
const outer = start === -1 ? '' : unfenced.substring(start, end > start ? end + 1 : unfenced.length);
const fromStart = start === -1 ? '' : unfenced.substring(start);
let parsed = tryParse(raw) || tryParse(unfenced) || (outer && tryParse(outer));
if (!parsed && outer) { try { parsed = tryParse(repairJson(outer)); } catch (e) { parsed = null; } }
if (!parsed && fromStart && fromStart !== outer) { try { parsed = tryParse(repairJson(fromStart)); } catch (e) { parsed = null; } }

if (!parsed) {
  return [{ json: { error: 'invalid_ai_output', raw: raw.substring(0, 2000) } }];
}

const values = (parsed.values && typeof parsed.values === 'object' && !Array.isArray(parsed.values)) ? parsed.values : {};
const names = schema.map(function (t) { return t.name; });
const rawXmlNames = schema.filter(function (t) { return t.type === 'rawXml'; }).map(function (t) { return t.name; });
const missing = Array.isArray(parsed.missing) ? parsed.missing.filter(function (n) { return names.indexOf(n) !== -1; }) : [];
const meta = (parsed.meta && typeof parsed.meta === 'object') ? parsed.meta : {};
const userFields = ['name', 'phone', 'email', 'designation', 'division'];
const userSource = Array.isArray(parsed.userSource) ? parsed.userSource.filter(function (u) {
  return u && names.indexOf(u.tag) !== -1 && userFields.indexOf(u.field) !== -1;
}).map(function (u) { return { tag: u.tag, field: u.field }; }) : [];
const diagramTags = Array.isArray(parsed.diagramTags) ? parsed.diagramTags.filter(function (n, i, all) { return rawXmlNames.indexOf(n) !== -1 && all.indexOf(n) === i; }) : [];

return [{ json: { values: values, missing: missing, userSource: userSource, diagramTags: diagramTags, quotationRef: typeof parsed.quotationRef === 'string' ? parsed.quotationRef : (typeof parsed.quotationRef === 'number' ? String(parsed.quotationRef) : ''), meta: { customerName: typeof meta.customerName === 'string' ? meta.customerName : '' } } }];

// Reference number of a Product + Solution proposal, built from the user's section / sub-section (sent as refRequest) and the quotation
// reference the AI read from the Excel:
//   section + sub-section + a usable Excel ref : SLTM-<SECTION>-<SUBSECTION>-SP<cleaned Excel ref>   e.g. SLTM-REBM-WPE-SP2026-0451 (no dash between SP and the ref)
//   section + sub-section, no usable Excel ref : SLTM-<SECTION>-<SUBSECTION>-SP
//   no section or no sub-section (admin)       : exactly "SLTM-"
// A reference that is already fixed (Regenerate sends refNo) is only echoed back. This node never throws: on any problem it answers refNo "" and the
// backend applies its own fallback ("SLTM-" or SLTM-<SECTION>-<SUBSECTION>-SP) - the reference can never stop a proposal.
const input = $input.first().json;
if (input.error) return [{ json: input }]; // the AI answer itself was unusable: pass it on unchanged

let refNo = '';
let refError = '';
let quotationRef = '';
try {
  const request = $('Webhook').first().json;
  const body = request.body || request;

  // The VALUE of the quotation reference, safe to use as the end of the reference number: label prefixes ("PR:", "PR -", "Ref:", "Ref No:",
  // "Quotation No:", "Quote #") removed, slashes / spaces -> "-", every character except letters, digits, ".", "_", "-" dropped.
  const cleanQuotationRef = function (raw) {
    var v = String(raw == null ? '' : raw).trim();
    var label = /^\s*(?:(?:quotation|quote|proposal|reference|ref|pr)\b\s*(?:no\.?|number|num\.?|#)?\s*[:#\-.]*\s*)+/i;
    for (var i = 0; i < 4; i++) { var next = v.replace(label, ''); if (next === v) break; v = next; }
    v = v.replace(/^[\s:#.\-]+/, '');
    return v.replace(/[\s\/\\]+/g, '-').replace(/[^A-Za-z0-9._-]/g, '').replace(/-{2,}/g, '-').replace(/^[-._]+|[-._]+$/g, '');
  };
  quotationRef = cleanQuotationRef(input.quotationRef);

  if (body.refNo) {
    refNo = String(body.refNo).trim();
  } else {
    const norm = function (v) { return String(v || '').toUpperCase().replace(/[^A-Z0-9]/g, ''); };
    const section = norm(body.refRequest && body.refRequest.section);
    const sub = norm(body.refRequest && body.refRequest.subSection);
    refNo = (section && sub) ? 'SLTM-' + section + '-' + sub + '-SP' + quotationRef : 'SLTM-';
  }
  if (!/^SLTM-(?:[A-Z0-9]+-[A-Z0-9]+-SP[A-Za-z0-9._-]*)?$/.test(refNo)) { refError = 'invalid reference ' + refNo; refNo = ''; }
} catch (e) {
  refNo = '';
  refError = String((e && e.message) || e);
}

return [{ json: Object.assign({}, input, { refNo: refNo, quotationRef: quotationRef }, refError ? { refError: refError } : {}) }];
